/* The translated GX demo: a PowerPC program (gx_demo_guest.c, generated by
 * tools/make_gx_demo.py) that draws a textured cube through GX every frame, presented with
 * the shared renderer in render/gx_scene.c. MIT License. */
#ifndef SPM3DS_GX_DEMO_H
#define SPM3DS_GX_DEMO_H

#include "gx_scene.h"

typedef struct {
    ppc_ctx *ctx;
    spm3ds_hw *hw;
    gx_scene scene;
} gx_demo;

int gx_demo_create(gx_demo *d);   /* 0 on success, negative step code otherwise */
void gx_demo_frame(gx_demo *d, C3D_RenderTarget *target, float angle_y, float angle_x);
void gx_demo_destroy(gx_demo *d);

#endif /* SPM3DS_GX_DEMO_H */
